const iiPower = {
  supply: { external: false, name: 'Apple II switching supply (Astec AA11040 family)', output: '+5 V 2.5 A; +12 V 1.5 A (2.5 A intermittent); -5 V 250 mA; -12 V 250 mA. 60 W continuous, 79 W intermittent', connector: 'ii-psu',
    notes: [
      'Flyback switching supply in a sealed case. Much of it sits at mains potential; Apple said no user repair.',
      'Needs a load. With the board unplugged it shuts down. Any fault (shorted rail, rail out of range) stops the oscillator; it retries about every 0.5 s, so you hear click-click-click or a squeal: the "dead PSU chirp". Chirping with the board connected means a short or overload: pull the cards, then the board, before you blame the supply.',
      'Minimum load about 9 W split roughly evenly between +5 V and +12 V. To bench-test it, load +5 V with about 5 Ω and +12 V with about 33 Ω (both 10 W or more).',
      'Only +5 V is regulated directly; the other rails track it, so a heavy +5 V load lifts them a little.',
      'Line input 107-132 V AC (some units switch to 214-264 V). Never apply more than 140 V AC.',
      'The yellow translucent RIFA X2 line-filter capacitors (usually 0.1 µF) crack with age and fail with a bang and acrid smoke. Replace them with X2-rated film capacitors of the same value. Some units have red WIMA caps instead.',
    ],
    sources: [
      { label: 'Apple II Reference Manual (1979), Power Supply, pp. 92-94', url: IIRM(102) },
      { label: 'Apple II Reference Manual (1979), protection and restart cycle, p. 94', url: IIRM(104) },
      { label: 'Apple II Red Book (1978), The Apple II Switching Power Supply, pp. 110-111', url: `${REDBOOK}#page=113` },
      { label: 'Applefritter: Apple II and IIe power supply RIFA replacements (forum)', url: 'https://www.applefritter.com/node/33594', verify: true },
    ] },
  rails: iiRails, testPoints: iiTests,
  firstTen: [
    { step: 1, check: 'Supply chirp', where: 'Power supply, cable off and then on the board', expect: 'Click-click or squeal with the cable off the board (no load: normal); runs quietly with the board on',
      ifNot: 'Chirping with the board on: a short or overload. Pull every card, then unplug the board, before you blame the supply.', source: { label: 'Apple II Reference Manual (1979), protection and restart cycle, p. 94', url: IIRM(104) } },
    { step: 2, check: 'Rails at the supply connector', where: 'ii-psu pin 3 (+5 V), ii-psu pin 4 (+12 V), ii-psu pin 6 (-5 V), ii-psu pin 5 (-12 V)', expect: '+4.85 to +5.15 V; +11.3 to +12.3 V; -4.7 to -5.7 V; -11 to -13 V (Red Book p. 111; nominals +5.0, +11.8, -5.2, -12.0 V on Reference Manual p. 92)',
      ifNot: 'One rail low with the board on: pull the cards, then look for a shorted chip on that rail (the 4116s use +12 V and -5 V).', source: { label: 'Apple II Reference Manual (1979), Power Supply specs, p. 92', url: IIRM(102) }, verify: true },
    { step: 3, check: 'Master oscillator', where: 'B2-10 (74S86 input, Sams UB2)', expect: '14.31818 MHz on a frequency counter',
      ifNot: 'Missing or off frequency: the oscillator transistors and crystal (Q1, Q2, XT001 in Sams).', source: S_CC1_TS },
    { step: 4, check: 'Timing dividers', where: 'B2-8 (14M); B1-15 (7M); B1-3 (colour reference); B1-7 (Φ0); B1-6 (Φ1); C2-12 (Q3)', expect: '14.318, 7.16, 3.58, 1.023, 1.023 and 2.05 MHz',
      ifNot: 'An output missing: the chip that makes it. Sams lists B1 74S175, B2 74S86, C2 74S195 and A2 74LS00 in the divider chain.', source: S_CC1_TS },
    { step: 5, check: 'CPU clock in', where: '6502 pin 37', expect: '1.023 MHz square', ifNot: 'Present at B1-7 but not here: the trace or the CPU socket.', source: SATHER_F32 },
    { step: 6, check: 'CPU running', where: '6502 pins 9 to 20 and 22 to 25 (address); 6502 pins 26 to 33 (data)', expect: 'Pulses on every line; pins 16 and 18 read LOW after power-on and pulse when RETURN is pressed',
      ifNot: 'A line stuck HIGH or LOW: follow it to the chips that share it before swapping the 6502.', source: S_CC1_TS },
    { step: 7, check: 'ROM and RAM selects', where: '9316B pins 20, 21; 4116 pin 15', expect: 'Pulses on a logic probe in the Monitor',
      ifNot: 'Sams gives Monitor ranges that exercise each ROM socket (D000.D7FF to F000.F7FF) and each RAM row.', source: S_CC1_TS2 },
  ],
  clocks: [
    { name: 'Crystal', where: 'Oscillator Q1, Q2 and XT001 (Sams designators); count it at B2-10', f: '14.31818 MHz', source: S_CC1_TS },
    { name: '14M', where: 'B2-8', f: '14.31818 MHz', source: SATHER_F32 },
    { name: '7M', where: 'B1-15; ii-slot pin 36', f: '7.15909 MHz', source: SATHER_T31 },
    { name: 'Colour reference', where: 'B1-3; ii-slot pin 35 (slot 7 only)', f: '3.579545 MHz', source: SATHER_T31 },
    { name: 'Q3', where: 'C2-12; ii-slot pin 37', f: '2.0454 MHz', note: 'Asymmetric. One cycle in 130 is long (0.629 µs).', source: SATHER_T31 },
    { name: 'Φ0 (CPU clock in)', where: 'B1-7; 6502 pin 37; ii-slot pin 40', f: '1.0227 MHz', note: 'Every 65th cycle is stretched to 1.117 µs, so the average is 1.0205 MHz.', source: SATHER_T31 },
    { name: 'Φ1', where: 'B1-6; ii-slot pin 38', f: '1.0227 MHz', note: 'Φ0 inverted.', source: SATHER_T31 },
    { name: '6502 Φ1 out', where: '6502 pin 3', f: '1.0227 MHz', note: 'The CPU\'s own Φ1 output: same rate as Φ0 on pin 37, in antiphase. The slots get PHASE 1 from the timing generator (B1-6), not from this pin.', verify: true, source: { label: 'MOS 6500 Microprocessors data sheet (Nov 1985), p. 4: 6502 clock timing, Φ1 (OUT) and Φ2 (OUT) follow Φ0 (IN)', url: 'http://archive.6502.org/datasheets/mos_6500_mpu_nov_1985.pdf#page=4' } },
  ],
  sources: [
    { label: 'Apple II Reference Manual (1979), Power Supply specs, p. 92', url: IIRM(102) },
    { label: 'Apple II Reference Manual (1979), Power Connector, p. 104', url: IIRM(114) },
    S_CC1_TIM, S_CC1_TS, SATHER_T31, SATHER_F32,
  ],
};

/* ---- Disk drives: Disk II (with its interface card), DuoDisk, UniDisk 5.25. Pins checked against the Apple
   schematics 050-0005-01 (interface card) and 050-0007-H (analog card), the Disk ][ Technical Procedures, Sather's
   "Understanding the Apple II" ch. 9 and the chip data sheets; see docs/verification/apple-drives.md. ---- */
Object.assign(RCS.terms, {
  stepper: { term: 'Stepper motor', short: 'Motor that moves the head one step per phase change.', long: 'The Disk II head is moved by a four-phase stepper. Software turns the phases on and off in order; two phase steps move the head one track. Ascending phases move the head inward (to track 34), descending outward to track 0.' },
  darlington: { term: 'Darlington driver', short: 'Two-transistor switch that sinks heavy current to ground.', long: 'A Darlington pair (as in the ULN2003) switches a coil or lamp to ground from a TTL input. Its output only sinks current; something else must pull it up. A dead driver leaves a coil permanently off or on.' },
  sequencer: { term: 'Logic state sequencer', short: 'PROM plus latch that runs as a tiny 2 MHz state machine.', long: 'On the Disk II controller the P6 PROM and a 74LS174 latch step through states on every Q3 clock, shifting bits into or out of the 74LS323 data register. Wrong or 13-sector P6 PROMs give a controller that steps and spins but never reads.' },
});

