        'Boots the built-in drive (slot 6, drive 1); an external 5.25 drive is slot 6, drive 2. Later IIcs then try a UniDisk 3.5 on port 5.',
        'Built-in ports stand in for slots: serial 1 (printer), serial 2 (modem), 80-column video at 3, mouse at 4 (port 7 on the memory-expansion IIc, which puts its RAM card at 4).',
